B.ak_=new A.bR("Cette formule est une r\xe9gression lin\xe9aire bas\xe9e sur le poids, la taille et l'\xe2ge. Elle est dans la lign\xe9e des formules de r\xe9f\xe9rence Harris-Benedict et Mifflin-St Jeor, dont elle partage la structure math\xe9matique.",!1,!1,null)
B.S=new A.c6(null,10,null,null)
